package fr.formation.clean.interfaceadapter.gateway;
import fr.formation.clean.application.boundary.*;import fr.formation.clean.application.usecase.UseCaseException;import fr.formation.clean.domain.entity.*;import jakarta.persistence.*;import java.time.LocalDateTime;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.stereotype.Component;
@Component class RoomJpaGateway implements RoomGateway{private final RoomRows rows;RoomJpaGateway(RoomRows rows){this.rows=rows;}public Room save(Room r){rows.save(new RoomRow(r.id(),r.name(),r.capacity()));return r;}public Optional<Room>findById(UUID id){return rows.findById(id).map(x->new Room(x.id,x.name,x.capacity));}public List<Room>findAll(){return rows.findAll().stream().map(x->new Room(x.id,x.name,x.capacity)).toList();}}
@Component class ReservationJpaGateway implements ReservationGateway{private final ReservationRows rows;ReservationJpaGateway(ReservationRows rows){this.rows=rows;}public Reservation save(Reservation r){rows.save(ReservationRow.of(r));return r;}public Optional<Reservation>findById(UUID id){return rows.findById(id).map(ReservationRow::entity);}public boolean hasOverlap(UUID roomId,LocalDateTime startsAt,LocalDateTime endsAt){return rows.overlaps(roomId,endsAt,startsAt);}}
interface RoomRows extends JpaRepository<RoomRow,UUID>{}interface ReservationRows extends JpaRepository<ReservationRow,UUID>{@org.springframework.data.jpa.repository.Query("select count(r)>0 from ReservationRow r where r.roomId=:roomId and r.status='CONFIRMED' and r.startsAt<:endsAt and r.endsAt>:startsAt")boolean overlaps(UUID roomId,LocalDateTime endsAt,LocalDateTime startsAt);}
@Entity @Table(name="rooms")class RoomRow{@Id UUID id;String name;int capacity;protected RoomRow(){}RoomRow(UUID id,String name,int capacity){this.id=id;this.name=name;this.capacity=capacity;}}
@Entity @Table(name="reservations")class ReservationRow{@Id UUID id;UUID roomId;String organizerEmail;int participants;LocalDateTime startsAt;LocalDateTime endsAt;String status;protected ReservationRow(){}static ReservationRow of(Reservation r){var x=new ReservationRow();x.id=r.id();x.roomId=r.roomId();x.organizerEmail=r.organizerEmail();x.participants=r.participants();x.startsAt=r.startsAt();x.endsAt=r.endsAt();x.status=r.status().name();return x;}Reservation entity(){return new Reservation(id,roomId,organizerEmail,participants,startsAt,endsAt,Reservation.Status.valueOf(status));}}
